wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3745850921864027)
,p_plug_name=>'Cards'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleB'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select count(*) total, ''Operators'' display from operator ',
'union all',
'select count(*) total, ''Tasks'' display from task',
'union',
'select count(*) total, ''Matches'' display',
'from table(',
'     matching(',
'     cursor(',
'            select operator, task',
'            from graph_table(g',
'            match (t is task)-[e is is_assigned]->(o is operator)',
'            columns (t.id as task, o.id as operator)',
'    )',
')))',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260327183750Z')
,p_updated_on=>wwv_flow_imp.dz('20260327190109Z')
